function normalize(value) {
  return value.replace(/\s+/g, " ").trim();
}

export function slug(value) {
  return normalize(value).replace(" ", "-").toLowerCase();
}

import { slug, tidyText } from "../src/text.js";

const failures = [];
if (slug(" Ship Release ") !== "ship-release") failures.push("slug regressed");
if (tidyText("  Release   Now ") !== "Release Now") failures.push("tidyText missing or wrong");
if (failures.length > 0) {
  console.error(failures.join("; "));
  process.exitCode = 1;
} else {
  console.log("ok");
}

